package io.lumine.mythic.lib.player.particle.type;
import io.lumine.mythic.lib.player.particle.*;import io.lumine.mythic.lib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import java.util.Map;
public class OffsetParticleEffect extends ParticleEffect{private final double speed,hOffset,vOffset,height;private final int amount;public OffsetParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed");height=resolveModifier(m,"height");hOffset=resolveModifier(m,"horizontal-offset");vOffset=resolveModifier(m,"vertical-offset");amount=(int)resolveModifier(m,"amount");}public OffsetParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed");height=o.getDouble("height");hOffset=o.getDouble("horizontal-offset");vOffset=o.getDouble("vertical-offset");amount=o.getInt("amount");}public ParticleEffectType getType(){return ParticleEffectType.OFFSET;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();particle.display(pl.getServerWorld(),pl.getPos().add(0,height,0),amount,hOffset,vOffset,hOffset,speed);}}
